function detectCustomOrderType(p){const id=String(p.id||'').toLowerCase(),name=String(p.name||p.nombre||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),cat=String(p.category||p.categoria||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const isCombo=/combo/.test(name)||/combo/.test(cat),isTaco=/taco/.test(name)||/taco/.test(cat),hasDouble=/(doble|double|2 proteinas|2 carnes)/.test(name),hasTriple=/(triple|3 proteinas|3 carnes)/.test(name);if(/custom[-_ ]*triple/.test(id)||(/personaliz/.test(name)&&/(triple|3 proteinas)/.test(name))||((isTaco||isCombo)&&hasTriple)||(/^triple/.test(name)&& (isCombo||isTaco)))return 'triple';if(/custom[-_ ]*double/.test(id)||(/personaliz/.test(name)&&/(doble|double|2 proteinas)/.test(name))||((isTaco||isCombo)&&hasDouble)||(/^doble/.test(name)&&(isCombo||isTaco)))return 'double';return p.orderType||null;}
