function mapDbProduct(r) {
  const rawAvailable =
    r.disponible ??
    r.available ??
    r.disponibilidad ??
    r.estado ??
    true;
  const value = String(rawAvailable)
    .trim()
    .toLowerCase();
  const unavailableValues = [
    'false',
    '0',
    'no',
    'agotado',
    'agotada',
    'unavailable',
    'out of stock',
    'sin stock'
  ];
  const available =
    rawAvailable !== false &&
    rawAvailable !== 0 &&
    !unavailableValues.includes(value);
  const p = {
    id: r.id,
    name: r.nombre,
    price: Number(r.precio) || 0,
    category: r.categoria,
    desc: r.descripcion || '',
    emoji: '🌮',
    image_url: r.imagen_url || '',
    images: Array.isArray(r.fotos) ? r.fotos : [],
    available
  };
  p.orderType = detectCustomOrderType(p);
  return p;
}
