function renderProductsRaw(){let q=document.getElementById('search').value.toLowerCase().trim();let list=products.filter(p=>(activeCategory==='Todos'||(activeCategory===POP_CAT?popIds.includes(String(p.id)):p.category===activeCategory))&&(`${p.name} ${p.desc} ${p.category}`).toLowerCase().includes(q));if(activeCategory===POP_CAT)list.sort((a,b)=>popRank(a)-popRank(b));const proteins=['Picadillo','Pechuga','Cerdo','Ropa vieja','Atún'];document.getElementById('products').innerHTML=list.length?list.map(p=>{let isCustom=!!p.orderType,n=p.orderType==='double'?2:(p.orderType==='triple'?3:0);let picks=isCustom?`<div class="customhint">Personaliza tus ${n} proteínas antes de añadirlo.</div><div class="proteinpick">${Array.from({length:n},(_,i)=>`<div><label for="${p.id}-protein-${i}">Proteína ${i+1}</label><select id="${esc(p.id)}-protein-${i}" data-protein-index="${i}"><option value="">Elige proteína</option>${proteins.map(pr=>`<option value="${pr}">${pr}</option>`).join('')}</select></div>`).join('')}</div>`:'';const imgs=[...new Set([...(p.images||[]),...(p.image_url?[p.image_url]:[])].filter(Boolean))].slice(0,3);return `<article class="product" data-product-id="${esc(p.id)}"><div class="productimg" onclick="openProductLightbox(this)" role="button" tabindex="0" aria-label="Ampliar foto de ${esc(p.name)}"><span class="tag">${esc(p.category)}</span>${imgs.length?`<img class="gallery-photo" loading="lazy" decoding="async" width="400" height="300" data-photo-index="0" src="${esc(imgs[0])}" alt="${esc(p.name)}" style="width:100%;height:100%;object-fit:cover"><span class="photo-name">${esc(p.name)}</span>${imgs.length>1?`<div class="gallerydots">${imgs.map((u,i)=>`<button class="${i===0?'active':''}" aria-label="Ver foto ${i+1}" onclick="event.stopPropagation();changeProductPhoto(this,${i})"></button>`).join('')}</div>`:''}`:(p.emoji||'🌮')}${!p.available?'<div class="soldout">AGOTADO</div>':''}</div><div class="productbody"><h3>${esc(p.name)}</h3>${!p.available?'<div class="product-status-soldout" role="status">AGOTADO · No disponible para pedir</div>':''}<p>${esc(p.desc||'Preparado por encargo.')}</p>${picks}<div class="productfoot"><span class="price">${money(p.price)}</span><button class="add" ${!p.available?'disabled':''} aria-label="Añadir ${esc(p.name)}" onclick="addToCart('${esc(p.id)}',this)">${p.available?'+':'×'}</button></div></div></article>`}).join(''):'<div class="empty" style="grid-column:1/-1">No encontramos productos con esa búsqueda.</div>';}

function changeProductPhoto(button,index){const card=button.closest('.productimg');const product=products.find(p=>String(p.id)===String(button.closest('.product')?.dataset.productId));if(!product)return;const imgs=[...new Set([...(product.images||[]),...(product.image_url?[product.image_url]:[])].filter(Boolean))].slice(0,3);const img=card.querySelector('.gallery-photo');if(img&&imgs[index])img.src=imgs[index];card.querySelectorAll('.gallerydots button').forEach((b,i)=>b.classList.toggle('active',i===index));}
function sortDeliveryZones(zones){return [...zones].sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'es',{sensitivity:'base'}));}
function renderDeliveryZones(){const sel=document.getElementById('deliveryZone');if(!sel)return;const currentName=sel.value!==''?siteSettings.delivery_zones[Number(sel.value)]?.name:'';siteSettings.delivery_zones=sortDeliveryZones(siteSettings.delivery_zones||[]);sel.innerHTML='<option value="">Seleccione su reparto</option>'+siteSettings.delivery_zones.map((z,i)=>`<option value="${i}">${esc(z.name)} — ${money(z.price)}</option>`).join('');if(currentName){const sortedIndex=siteSettings.delivery_zones.findIndex(z=>z.name===currentName);if(sortedIndex>=0)sel.value=String(sortedIndex);}updateDeliveryCost();}
function selectedDeliveryZone(){const sel=document.getElementById('deliveryZone');return sel&&sel.value!==''?siteSettings.delivery_zones[Number(sel.value)]:null;}
function updateDeliveryCost(){const z=selectedDeliveryZone();const hint=document.getElementById('deliveryPriceHint');if(hint)hint.textContent=z?`Costo del domicilio: ${money(z.price)}`:'Seleccione una zona para ver el costo del domicilio.';renderCart();}
function chooseService(value){openCart();const radio=document.querySelector(`input[name="deliveryChoice"][value="${value}"]`);if(radio&&!radio.closest('label').classList.contains('hidden')){radio.checked=true;toggleAddress();radio.dispatchEvent(new Event('change',{bubbles:true}));}else{notify(value==='yes'?'El servicio de domicilio no está disponible ahora.':'La recogida no está disponible ahora.');}}
let lightboxPhotos=[],lightboxIndex=0,lightboxName='';
function paintLightbox(){const box=document.getElementById('productLightbox'),img=box.querySelector('img');if(!lightboxPhotos.length)return;img.src=lightboxPhotos[lightboxIndex];img.alt=lightboxName;box.querySelector('.lightbox-title').textContent=lightboxName;const count=box.querySelector('.lightbox-count');if(count)count.textContent=lightboxPhotos.length>1?`${lightboxIndex+1} / ${lightboxPhotos.length}`:'';box.querySelector('.lightbox-prev').classList.toggle('hidden',lightboxPhotos.length<2);box.querySelector('.lightbox-next').classList.toggle('hidden',lightboxPhotos.length<2);}
function openProductLightbox(el){const img=el.querySelector('.gallery-photo');if(!img)return;const product=products.find(p=>String(p.id)===String(el.closest('.product')?.dataset.productId));lightboxPhotos=[...new Set([...(product?.images||[]),...(product?.image_url?[product.image_url]:[])].filter(Boolean))].slice(0,3);if(!lightboxPhotos.length)lightboxPhotos=[img.src];lightboxIndex=Math.max(0,lightboxPhotos.findIndex(src=>src===img.src||src===img.getAttribute('src')));lightboxName=product?.name||img.alt;const box=document.getElementById('productLightbox');paintLightbox();box.classList.add('open');document.body.style.overflow='hidden';}
function moveLightboxPhoto(delta){if(lightboxPhotos.length<2)return;lightboxIndex=(lightboxIndex+delta+lightboxPhotos.length)%lightboxPhotos.length;paintLightbox();}
function closeProductLightbox(){document.getElementById('productLightbox').classList.remove('open');document.body.style.overflow='';}
(function setupLightboxSwipe(){const box=document.getElementById('productLightbox');if(!box)return;let startX=0,startY=0;box.addEventListener('touchstart',e=>{if(!e.touches||!e.touches.length)return;startX=e.touches[0].clientX;startY=e.touches[0].clientY;},{passive:true});box.addEventListener('touchend',e=>{if(!e.changedTouches||!e.changedTouches.length)return;const dx=e.changedTouches[0].clientX-startX,dy=e.changedTouches[0].clientY-startY;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.2)moveLightboxPhoto(dx<0?1:-1);},{passive:true});})();
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const m=document.querySelector('.modalback.open');if(m)closeModal(m.id)}if((e.key==='Enter'||e.key===' ')&&e.target&&e.target.matches&&e.target.matches('.productimg[role="button"]')){e.preventDefault();e.target.click()}if(e.key==='Escape')closeProductLightbox();else if(document.getElementById('productLightbox').classList.contains('open')&&e.key==='ArrowRight')moveLightboxPhoto(1);else if(document.getElementById('productLightbox').classList.contains('open')&&e.key==='ArrowLeft')moveLightboxPhoto(-1);});
function populateReviewProducts(){const sel=document.getElementById('reviewProduct');if(!sel)return;const current=sel.value;sel.innerHTML='<option value="">Reseña general de Tacos Mishos</option>'+products.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');sel.value=current;}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function updateProteinChoices(card){const selects=[...card.querySelectorAll('select[data-protein-index]')];const chosen=selects.map(s=>s.value).filter(Boolean);selects.forEach(select=>{const current=select.value;[...select.options].forEach(option=>{if(!option.value)return;option.disabled=option.value!==current&&chosen.includes(option.value);});});}
document.addEventListener('change',event=>{if(event.target.matches('select[data-protein-index]'))updateProteinChoices(event.target.closest('.product'));});
function addToCart(id,button){let p=products.find(x=>String(x.id)===String(id));if(!p)return;if(!p.available){notify('Este producto está agotado por el momento.');return}let proteins=[];if(p.orderType){let n=p.orderType==='double'?2:3;let card=button.closest('.product');for(let i=0;i<n;i++){let select=card.querySelector(`select[data-protein-index="${i}"]`);let v=select?.value||'';if(!v){notify(`Elige la proteína ${i+1} para personalizar tu combo.`);select?.focus();return}if(proteins.includes(v)){notify('Elige una proteína diferente en cada taco; no puedes repetir proteínas.');select?.focus();return}proteins.push(v)}}let key=proteins.length?String(id)+'::'+proteins.join('|'):String(id);cart[key]=(cart[key]||0)+1;saveCart();updateCartCount();tmBuzz(15);tmFlyToCart(button,p);const toast=document.getElementById('toast');toast.textContent='✓ '+p.name+' añadido al carrito';toast.classList.add('show');clearTimeout(window.tmToastTimer);window.tmToastTimer=setTimeout(()=>toast.classList.remove('show'),1800);}

function tmFab(force){const f=document.getElementById('fab');if(!f)return;const on=force===undefined?!f.classList.contains('open'):force;if(on===f.classList.contains('open'))return;if(on&&window.tmFabOrient)window.tmFabOrient();f.classList.toggle('open',on);if(on&&!lsGet('tm_fab_tip')){lsSet('tm_fab_tip','1');setTimeout(()=>notify('Tip: arrastra el botón del menú para moverlo donde quieras.'),500)}const t=f.querySelector('.fab-toggle');t.setAttribute('aria-expanded',String(on));t.setAttribute('aria-label',on?'Cerrar menú':'Abrir menú');tmBuzz(8)}
document.addEventListener('keydown',e=>{if(e.key==='Escape')tmFab(false)});
function tmReduced(){return !!(window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches)}
function tmStaggerGrid(){const g=document.getElementById('products');if(!g||tmReduced())return;g.querySelectorAll('.product').forEach((c,i)=>c.style.setProperty('--i',Math.min(i,10)));g.classList.remove('stagger');void g.offsetWidth;g.classList.add('stagger');clearTimeout(window.tmStagT);window.tmStagT=setTimeout(()=>g.classList.remove('stagger'),1500)}
function tmShowSkeleton(){const g=document.getElementById('products');if(!g)return;g.setAttribute('aria-busy','true');g.innerHTML=Array(6).fill('<article class="product skel-card" aria-hidden="true"><div class="skel skel-img"></div><div class="skel skel-line w70" style="margin-top:20px"></div><div class="skel skel-line w90"></div><div class="skel skel-line w40"></div></article>').join('')}
function tmEndSkeleton(){const g=document.getElementById('products');if(g)g.removeAttribute('aria-busy');if(g&&g.querySelector('.skel-card')){categories();renderProducts();tmStaggerGrid()}}
function tmPopQty(key){tmBuzz(8);if(tmReduced())return;const el=[...document.querySelectorAll('#cartItems .qn')].find(e=>e.dataset.k===key);if(el&&el.animate)el.animate([{transform:'scale(1)'},{transform:'scale(1.25)'},{transform:'scale(.92)'},{transform:'scale(1)'}],{duration:380,easing:'cubic-bezier(.3,1.6,.5,1)'})}
function tmSendMorph(btn){if(!btn)return;btn.dataset.html=btn.innerHTML;btn.disabled=true;btn.classList.add('is-ok');btn.setAttribute('aria-label','Pedido listo');btn.innerHTML='<svg viewBox="0 0 24 24" width="30" height="30" aria-hidden="true"><path class="chk" d="M5 12.5l4.5 4.5L19 7.5" pathLength="1" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>';tmBuzz([15,30,15])}
function tmSendReset(btn){if(!btn)return;btn.classList.remove('is-ok');btn.disabled=false;btn.removeAttribute('aria-label');if(btn.dataset.html)btn.innerHTML=btn.dataset.html}
(function tmFabDrag(){const f=document.getElementById('fab'),t=f&&f.querySelector('.fab-toggle');if(!f||!t)return;const M=8;let sx=0,sy=0,ox=0,oy=0,drag=false,pid=null;
const S=()=>t.offsetWidth||56,VW=()=>document.documentElement.clientWidth,VH=()=>window.innerHeight;
function place(x,y){x=Math.max(M,Math.min(VW()-S()-M,x));y=Math.max(M,Math.min(VH()-S()-M,y));f.style.left=x+'px';f.style.top=y+'px';f.style.bottom='auto';f.style.right='auto'}
function orient(){const r=f.getBoundingClientRect();f.classList.toggle('down',r.top+r.height/2<VH()/2);f.classList.toggle('right',r.left+r.width/2>VW()/2)}
function save(){const r=f.getBoundingClientRect();lsSet('tm_fab_v1',JSON.stringify({x:(r.left-M)/Math.max(1,VW()-S()-2*M),y:(r.top-M)/Math.max(1,VH()-S()-2*M)}))}
function restore(){try{const p=JSON.parse(lsGet('tm_fab_v1')||'null');if(!p||typeof p.x!=='number'||typeof p.y!=='number')return false;place(M+p.x*(VW()-S()-2*M),M+p.y*(VH()-S()-2*M));return true}catch(e){return false}}
t.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;const r=f.getBoundingClientRect();sx=e.clientX;sy=e.clientY;ox=r.left;oy=r.top;drag=false;pid=e.pointerId;try{t.setPointerCapture(pid)}catch(_){}});
t.addEventListener('pointermove',e=>{if(pid!==e.pointerId)return;const dx=e.clientX-sx,dy=e.clientY-sy;if(!drag&&Math.hypot(dx,dy)<6)return;if(!drag){drag=true;f.classList.add('dragging');tmFab(false)}place(ox+dx,oy+dy)});
const end=e=>{if(pid!==e.pointerId)return;pid=null;f.classList.remove('dragging');if(drag){window.tmFabMoved=true;setTimeout(()=>{window.tmFabMoved=false},80);orient();save()}drag=false};
t.addEventListener('pointerup',end);t.addEventListener('pointercancel',end);
window.addEventListener('resize',()=>{restore();orient()});
window.tmFabOrient=orient;restore();orient();})();
const CLEAR_BTN='<button type="button" class="clearbtn" onclick="clearCart(this)">🗑️ Vaciar pedido</button>';
function norm(x){return String(x||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function applyTicker(){const sp=document.querySelector('#announcementTicker>span');if(!sp)return;const t=(window.tmClosedMsg?window.tmClosedMsg+'   ·   ':'')+(siteSettings.announcement||'');if(sp.textContent!==t)sp.textContent=t}
function popRank(p){const i=popIds.indexOf(String(p.id));return i<0?999:i}
function popProducts(){return popIds.map(id=>products.find(p=>String(p.id)===id)).filter(p=>p&&p.available&&!p.orderType)}
function renderPopular(){const box=document.getElementById('popular');if(!box)return;const list=popProducts().slice(0,6);if(!list.length){box.hidden=true;box.innerHTML='';return}box.innerHTML='<h3 class="pop-title">🔥 Los más pedidos</h3><div class="pop-row">'+list.map(p=>{const img=(p.images&&p.images[0])||p.image_url||'';return `<div class="mini" data-product-id="${esc(p.id)}"><div class="mini-img">${img?`<img class="gallery-photo" loading="lazy" decoding="async" width="120" height="120" src="${esc(img)}" alt="">`:`<span>${esc(p.emoji||'🌮')}</span>`}</div><div class="mini-name">${esc(p.name)}</div><div class="mini-foot"><b>${money(p.price)}</b><button type="button" class="add" aria-label="Añadir ${esc(p.name)}" onclick="addToCart('${esc(p.id)}',this)">+</button></div></div>`}).join('')+'</div>';box.hidden=false}
async function loadPopular(){try{if(!window.tmSupabase)return;const r=await window.tmSupabase.rpc('productos_populares',{p_limit:10});if(r.error)throw r.error;popIds=(r.data||[]).map(x=>String(x.id));lsSet('tm_pop_v1',JSON.stringify(popIds));categories();renderPopular();if(activeCategory===POP_CAT)renderProducts()}catch(e){console.warn('Más pedidos no disponible:',e)}}
function catScroll(d){const sc=document.getElementById('categories');if(sc)sc.scrollBy({left:d*Math.max(160,sc.clientWidth*.6),behavior:'smooth'})}
(function(){const sc=document.getElementById('categories');if(!sc)return;const w=sc.parentElement;const upd=()=>{const max=sc.scrollWidth-sc.clientWidth;w.classList.toggle('can-left',sc.scrollLeft>4);w.classList.toggle('can-right',sc.scrollLeft<max-4)};sc.addEventListener('scroll',upd,{passive:true});window.addEventListener('resize',upd);new MutationObserver(upd).observe(sc,{childList:true});if('ResizeObserver' in window)new ResizeObserver(upd).observe(sc);upd()})();
function clearCart(btn){if(btn&&!btn.dataset.armed){btn.dataset.armed='1';btn.textContent='¿Seguro? Toca otra vez';clearTimeout(window.tmClrT);window.tmClrT=setTimeout(()=>{btn.dataset.armed='';btn.textContent='🗑️ Vaciar pedido'},3000);return}cart={};window.tmSugOff=false;saveCart();updateCartCount();renderCart();tmBuzz([10,30,10]);notify('Pedido vaciado. Puedes empezar uno nuevo.')}
function renderSuggest(items){const box=document.getElementById('suggestBox');if(!box)return;const hasCombo=items.some(it=>/combo/.test(norm(it.product.category+' '+it.product.name)));if(!hasCombo||window.tmSugOff){box.hidden=true;box.innerHTML='';return}const has=re=>items.some(it=>re.test(norm(it.product.category)));const pick=(re,pref)=>{const l=products.filter(p=>p.available&&!p.orderType&&re.test(norm(p.category)));return l.find(p=>pref&&pref.test(norm(p.name)))||l.sort((a,b)=>a.price-b.price)[0]};const out=[];if(!has(/salsa/)){const p=pick(/salsa/,/casa/);if(p)out.push([p,'¿Añadir '+p.name.toLowerCase()+'?'])}if(!has(/bebida/)){const p=pick(/bebida/);if(p)out.push([p,'¿Algo para tomar? '+p.name])}if(!out.length){box.hidden=true;box.innerHTML='';return}box.innerHTML='<div class="sug-title">✨ Complementa tu pedido<button type="button" class="sug-x" aria-label="No mostrar sugerencias" onclick="window.tmSugOff=true;renderCart()">✕</button></div>'+out.map(([p,q])=>`<div class="sug-row"><span>${esc(q)}</span><button type="button" class="sug-add" onclick="addSuggested('${esc(p.id)}')">+ ${money(p.price)}</button></div>`).join('');box.hidden=false}
function addSuggested(id){cart[id]=(cart[id]||0)+1;saveCart();updateCartCount();renderCart();tmBuzz(12);tmBumpCart()}
function renderSent(){const box=document.getElementById('sentCard');if(!box)return;let d=null;try{d=JSON.parse(lsGet('tm_sent_v1')||'null')}catch(e){}if(!d||!d.url||Date.now()-d.t>12*36e5){box.hidden=true;return}const m=Math.max(0,Math.round((Date.now()-d.t)/6e4)),ago=m<1?'justo ahora':m<60?`hace ${m} min`:`hace ${Math.round(m/60)} h`;const html=`<div class="sent-info"><b>✅ Pedido enviado</b><div class="small">${ago} · ${d.n} producto${d.n>1?'s':''} · ${money(d.total)}. ¿No se abrió WhatsApp?</div></div><div class="sent-acts"><button class="primary mintbtn" type="button" onclick="resendOrder()">Reenviar por WhatsApp</button><button class="secondary" type="button" onclick="dismissSent()">Listo</button></div>`;if(box.innerHTML!==html)box.innerHTML=html;box.hidden=false}
function resendOrder(){try{const d=JSON.parse(lsGet('tm_sent_v1')||'null');if(!d)return;const w=window.open(d.url,'_blank');if(!w)location.href=d.url}catch(e){}}
function dismissSent(){lsDel('tm_sent_v1');renderSent()}
function tmBuzz(p){try{if(navigator.vibrate)navigator.vibrate(p)}catch(e){}}
function tmBumpCart(){const reduce=window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches;if(reduce)return;const b=document.querySelector('.cartbtn'),c=document.getElementById('cartCount');if(b&&b.animate)b.animate([{transform:'scale(1)'},{transform:'scale(1.12)'},{transform:'scale(.96)'},{transform:'scale(1)'}],{duration:450,easing:'ease-out'});if(c&&c.animate)c.animate([{transform:'scale(1)'},{transform:'scale(1.7)'},{transform:'scale(.9)'},{transform:'scale(1.2)'},{transform:'scale(1)'}],{duration:550,easing:'cubic-bezier(.3,1.6,.5,1)'})}
function tmFlyToCart(btn,p){const reduce=window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches;const target=document.getElementById('cartCount');if(!btn||!target||reduce||!btn.animate){tmBumpCart();return}const card=btn.closest('.product,.mini'),src=card&&card.querySelector('.gallery-photo'),size=56;let el;if(src&&src.currentSrc){el=document.createElement('img');el.src=src.currentSrc;el.alt=''}else{el=document.createElement('div');el.textContent=(p&&p.emoji)||'🌮';el.style.cssText='display:grid;place-items:center;font-size:32px;background:var(--sage)'}el.className='flyer';el.style.width=el.style.height=size+'px';const a=btn.getBoundingClientRect(),t=target.getBoundingClientRect();const x0=a.left+a.width/2-size/2,y0=a.top+a.height/2-size/2,dx=t.left+t.width/2-size/2-x0,dy=t.top+t.height/2-size/2-y0;el.style.left=x0+'px';el.style.top=y0+'px';document.body.appendChild(el);const done=()=>{if(el.parentNode)el.remove();tmBumpCart()};const an=el.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${dx*.55}px,${dy*.55-90}px) scale(.8)`,opacity:1,offset:.5},{transform:`translate(${dx}px,${dy}px) scale(.25)`,opacity:.7}],{duration:750,easing:'cubic-bezier(.45,.05,.35,1)'});an.onfinish=done;an.oncancel=done}
function updateCartCount(){const cn=document.getElementById('cartCount'),cntTotal=Object.values(cart).reduce((a,b)=>a+b,0);cn.textContent=cntTotal;cn.classList.toggle('zero',!cntTotal);try{renderRepeat()}catch(e){}}
function openCart(){window.tmLastFocus=document.activeElement;renderCart();fetchLoyalty();updateEta();document.getElementById('cartModal').classList.add('open');setTimeout(()=>{const c=document.querySelector('#cartModal .close');if(c)c.focus()},50)}
function closeModal(id){document.getElementById(id).classList.remove('open');try{if(window.tmLastFocus&&window.tmLastFocus.focus)window.tmLastFocus.focus()}catch(e){}}
function cartEntries(){return Object.entries(cart).filter(([key,qty])=>qty>0).map(([key,qty])=>{let [id,proteinText]=key.split('::');let product=products.find(p=>p.id===id);return product?{key,id,qty,product,proteins:proteinText?proteinText.split('|'):[]}:null}).filter(Boolean)}
function fmtPhone(n){n=String(n).replace(/\D/g,'');return n.length===10&&n.startsWith('53')?'+53 '+n.slice(2,6)+' '+n.slice(6):'+'+n}
function fillWaChoice(){const sel=document.getElementById('waChoice');if(!sel)return;let nums=[settings.whatsapp,settings.whatsapp2].map(x=>String(x||'').replace(/\D/g,'')).filter(x=>x.length>=8);if(!nums.length)nums=WA_DEFAULTS.slice();const cur=sel.value;sel.innerHTML=nums.map(n=>`<option value="${esc(n)}">📱 ${esc(fmtPhone(n))}</option>`).join('');if(nums.includes(cur))sel.value=cur;}
function rememberCustomer(name,phone,address,zoneName,service){lsSet('tm_customer_v1',JSON.stringify({name,phone,address,zoneName,service}))}
function restoreCustomer(){try{const c=JSON.parse(lsGet('tm_customer_v1')||'null');if(!c)return;const set=(id,v)=>{const el=document.getElementById(id);if(el&&v&&!el.value)el.value=v};set('customerName',c.name);set('customerPhone',c.phone);if(c.service&&!document.querySelector('input[name="deliveryChoice"]:checked')){const r=document.querySelector(`input[name="deliveryChoice"][value="${c.service}"]`);if(r&&!r.closest('label').classList.contains('hidden')){r.checked=true;toggleAddress();}}if(c.service==='yes'){set('customerAddress',c.address);const sel=document.getElementById('deliveryZone');if(sel&&c.zoneName&&sel.value===''){const i=(siteSettings.delivery_zones||[]).findIndex(z=>z.name===c.zoneName);if(i>=0){sel.value=String(i);updateDeliveryCost();}}}}catch(e){}}
function forgetCustomer(){lsDel('tm_customer_v1');['customerName','customerPhone','customerAddress'].forEach(id=>{const el=document.getElementById(id);if(el)el.value=''});const z=document.getElementById('deliveryZone');if(z)z.value='';document.querySelectorAll('input[name="deliveryChoice"]').forEach(el=>el.checked=false);toggleAddress();notify('Borramos tus datos guardados en este teléfono.');}
function notify(msg){const t=document.getElementById('toast');if(!t)return;t.textContent=msg;t.classList.add('show');clearTimeout(window.tmToastTimer);window.tmToastTimer=setTimeout(()=>t.classList.remove('show'),Math.min(7000,2500+String(msg).length*40));}
