function renderSocial(){const boxes=document.querySelectorAll('.js-social');if(!boxes.length)return;const ok=u=>/^https:\/\//.test(String(u||''));const items=[['instagram','Instagram',siteSettings.instagram_url||SOCIAL.instagram],['facebook','Facebook',siteSettings.facebook_url||SOCIAL.facebook],['whatsapp','Grupo de WhatsApp',siteSettings.whatsapp_group_url||SOCIAL.whatsapp]].filter(x=>ok(x[2]));boxes.forEach(b=>b.innerHTML=items.map(([k,t,u])=>`<a class="soc-${k}" href="${esc(u)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(t)}" title="${esc(t)}"><svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true" focusable="false"><path fill="currentColor" d="${SOCIAL_ICONS[k]}"/></svg></a>`).join(''));}
function markToday(){const w=new Date().toLocaleDateString('en-US',{weekday:'short',timeZone:'America/Havana'});const d=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(w);document.querySelectorAll('#aboutHours li').forEach(li=>li.classList.toggle('today',li.dataset.days.split(',').includes(String(d))))}
if('serviceWorker' in navigator&&(location.protocol==='https:'||location.hostname==='localhost')){window.addEventListener('load',()=>{navigator.serviceWorker.register('sw.js').catch(()=>{})})}
let tmInstallEvt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();tmInstallEvt=e;const b=document.getElementById('installBtn');if(b)b.hidden=false});
window.addEventListener('appinstalled',()=>{tmInstallEvt=null;const b=document.getElementById('installBtn');if(b)b.hidden=true;notify('¡Listo! Tacos Mishos quedó instalada en tu teléfono.')});
async function installApp(){if(!tmInstallEvt)return;tmInstallEvt.prompt();try{await tmInstallEvt.userChoice}catch(e){}tmInstallEvt=null;const b=document.getElementById('installBtn');if(b)b.hidden=true}
function toggleNavSearch(force){const nav=document.querySelector('.nav'),inp=document.getElementById('navSearch'),main=document.getElementById('search');const on=force===undefined?!nav.classList.contains('searching'):force;nav.classList.toggle('searching',on);if(on){if(!document.getElementById('page-menu').classList.contains('active'))showPage('page-menu');inp.value=main.value;setTimeout(()=>inp.focus(),30)}else{inp.value='';if(main.value){main.value='';renderProducts()}}}
function onNavSearch(v){const main=document.getElementById('search');main.value=v;if(v.trim()&&activeCategory!=='Todos'){activeCategory='Todos';categories()}onSearchInput();if(v.trim()){clearTimeout(window.tmScrollT);window.tmScrollT=setTimeout(()=>{const g=document.getElementById('products');if(!g)return;const t=g.getBoundingClientRect().top;if(t>window.innerHeight*.55||t<0)g.scrollIntoView({behavior:'smooth',block:'start'})},260)}}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.nav.searching'))toggleNavSearch(false)});
// ===== Pedidos guardados · fidelidad · repetir pedido · tiempo estimado =====
const LOYALTY={sauce:3,free:8};
function etaText(service){return service==='yes'||service==='domicilio'?(siteSettings.eta_domicilio||'40–60 min'):(siteSettings.eta_recogida||'20–30 min')}
function updateEta(){const box=document.getElementById('etaBox');if(!box)return;const c=document.querySelector('input[name="deliveryChoice"]:checked');if(!c){box.hidden=true;return}box.hidden=false;box.textContent=(c.value==='yes'?'🛵 Entrega a domicilio: ':'🏪 Para recoger: ')+'tiempo estimado '+etaText(c.value)+' desde que confirmemos tu pedido.'}
async function registerOrder(o){if(!window.tmSupabase)return{};try{const call=window.tmSupabase.rpc('crear_pedido',{p_nombre:o.name,p_telefono:o.phone,p_servicio:o.delivery==='yes'?'domicilio':'recogida',p_zona:o.zone?o.zone.name:null,p_direccion:o.delivery==='yes'?o.address:null,p_items:o.items.map(it=>({id:it.id,nombre:it.product.name,cantidad:it.qty,proteinas:it.proteins,precio:it.product.price})),p_subtotal:o.productsTotal,p_envio:o.deliveryCost,p_total:o.total,p_notas:o.notes||null});const r=await Promise.race([call,new Promise((_,rej)=>setTimeout(()=>rej(new Error('timeout')),4500))]);if(r.error)throw r.error;return r.data||{}}catch(e){console.warn('No se pudo registrar el pedido:',e);return{}}}
let loyaltyTimer;
function renderLoyalty(d){const box=document.getElementById('loyaltyBox');if(!box)return;if(!d||typeof d.completados!=='number'){box.hidden=true;return}const n=d.completados%LOYALTY.free,pos=n+1;const dots=Array.from({length:LOYALTY.free},(_,i)=>{const k=i+1,gift=k===LOYALTY.sauce||k===LOYALTY.free;return `<span class="dot ${k<=n?'done':''} ${k===pos?'now':''}">${gift?'🎁':k}</span>`}).join('');const msg=pos===LOYALTY.sauce?'🎁 ¡Este pedido lleva una <b>salsa gratis</b>!':pos===LOYALTY.free?'🎉 ¡Este pedido es <b>GRATIS</b>! Te lo confirmamos por WhatsApp.':pos<LOYALTY.sauce?`Después de este pedido te faltan <b>${LOYALTY.sauce-pos}</b> para tu salsa gratis.`:`Después de este pedido te faltan <b>${LOYALTY.free-pos}</b> para tu pedido gratis.`;box.innerHTML=`<b>⭐ Tu tarjeta de premios</b><div class="dots">${dots}</div><div>${msg}</div><small>Cuentan los pedidos que ya te entregamos.</small>`;box.hidden=false}
async function fetchLoyalty(){const ph=(document.getElementById('customerPhone')||{}).value||'';if(!/^\d{8,15}$/.test(ph)||!window.tmSupabase){renderLoyalty(null);return}try{const r=await window.tmSupabase.rpc('puntos_cliente',{p_telefono:ph});renderLoyalty(r.error?null:r.data)}catch(e){renderLoyalty(null)}}
function repeatEntries(){let last;try{last=JSON.parse(lsGet('tm_last_cart_v1')||'null')}catch(e){last=null}if(!last||typeof last!=='object')return[];return Object.entries(last).map(([key,qty])=>{const id=key.split('::')[0],p=products.find(x=>String(x.id)===id);return p&&p.available&&Number(qty)>0?{key,qty:Number(qty),p}:null}).filter(Boolean)}
function renderRepeat(){const box=document.getElementById('repeatCard');if(!box||window.tmRepeatBusy)return;const e=repeatEntries(),n=e.reduce((a,x)=>a+x.qty,0);if(!n||Object.keys(cart).length){box.hidden=true;return}const total=e.reduce((s,x)=>s+x.p.price*x.qty,0);const html=`<button class="repeatbtn" type="button" onclick="repeatLast(this)"><span class="rb-ico" aria-hidden="true">🔄</span><span class="rb-txt">Repetir último pedido (${money(total)})</span></button>`;if(box.innerHTML!==html)box.innerHTML=html;box.hidden=false}
function repeatLast(btn){const e=repeatEntries();if(!e.length||window.tmRepeatBusy)return;window.tmRepeatBusy=true;e.forEach(x=>{cart[x.key]=(cart[x.key]||0)+x.qty});saveCart();updateCartCount();tmBuzz([20,40,20]);const t=btn&&btn.querySelector('.rb-txt'),i=btn&&btn.querySelector('.rb-ico');if(btn){btn.classList.add('is-squeeze');setTimeout(()=>{btn.classList.remove('is-squeeze');btn.classList.add('is-done');if(t)t.textContent='¡Pedido clonado con éxito!';if(i)i.textContent='✔️'},180);setTimeout(()=>{btn.classList.add('is-bounce');tmBumpCart()},750)}setTimeout(()=>{window.tmRepeatBusy=false;renderRepeat()},2600)}
document.addEventListener('input',e=>{if(e.target&&e.target.id==='customerPhone'){clearTimeout(loyaltyTimer);loyaltyTimer=setTimeout(fetchLoyalty,500)}});
document.addEventListener('change',e=>{if(e.target&&e.target.name==='deliveryChoice')updateEta()});
function renderCart(){let items=cartEntries();document.getElementById('cartItems').innerHTML=items.length?items.map(it=>`<div class="cartrow"><div><b>${esc(it.product.name)}</b>${it.proteins.length?`<div class="tiny">Proteínas: ${it.proteins.map(esc).join(' + ')}</div>`:''}<div class="tiny">${money(it.product.price)} c/u</div></div><div class="qty"><button onclick="changeQty('${it.key.replace(/'/g,"\\'")}',-1)">−</button><b class="qn" data-k="${esc(it.key)}">${it.qty}</b><button onclick="changeQty('${it.key.replace(/'/g,"\\'")}',1)">+</button><span style="min-width:72px;text-align:right;font-weight:800">${money(it.product.price*it.qty)}</span></div></div>`).join('')+CLEAR_BTN:'<div class="empty">Tu carrito está vacío. Añade algo rico del menú.</div>';const productsTotal=items.reduce((s,it)=>s+it.product.price*it.qty,0);const choice=document.querySelector('input[name="deliveryChoice"]:checked')?.value;const zone=choice==='yes'?selectedDeliveryZone():null;document.getElementById('cartTotal').textContent=money(productsTotal+(zone?Number(zone.price)||0:0));try{renderSuggest(items)}catch(e){}}
function changeQty(key,d){cart[key]=(cart[key]||0)+d;if(cart[key]<=0)delete cart[key];saveCart();updateCartCount();renderCart();tmPopQty(key);}

function toggleAddress(){const choice=document.querySelector('input[name="deliveryChoice"]:checked');const yes=choice?.value==='yes';document.getElementById('addressField').classList.toggle('hidden',!yes);document.getElementById('exactAddressField').classList.toggle('hidden',!yes);document.getElementById('customerAddress').required=yes;document.getElementById('deliveryZone').required=yes;if(!yes){document.getElementById('customerAddress').value='';document.getElementById('deliveryZone').value='';}updateDeliveryCost();}
async function sendOrder(){if(window.tmSending)return;let items=cartEntries();if(!items.length){notify('Añade al menos un producto al pedido.');return}let name=document.getElementById('customerName').value.trim(),phone=document.getElementById('customerPhone').value.trim(),delivery=document.querySelector('input[name="deliveryChoice"]:checked')?.value,address=document.getElementById('customerAddress').value.trim(),zone=delivery==='yes'?selectedDeliveryZone():null;if(!name||!phone){notify('Completa tu nombre y teléfono.');return}if(!/^[A-Za-zÁÉÍÓÚÜÑáéíóúüñ]+(?:[ '’-][A-Za-zÁÉÍÓÚÜÑáéíóúüñ]+)*$/.test(name)){notify('El nombre solo puede contener letras y espacios.');document.getElementById('customerName').focus();return}if(!/^\d{8,15}$/.test(phone)){notify('El teléfono debe contener únicamente números (entre 8 y 15 dígitos).');document.getElementById('customerPhone').focus();return}if(!delivery){notify('Marca el servicio que deseas: entrega a domicilio o recoger en el local.');return}if(delivery==='yes'&&!siteSettings.delivery_enabled){notify('El servicio de delivery está temporalmente desactivado.');return}if(delivery==='no'&&!siteSettings.pickup_enabled){notify('La recogida en el local está temporalmente desactivada.');return}if(delivery==='yes'&&!zone){notify('Selecciona tu reparto.');return}if(delivery==='yes'&&!address){notify('Escribe la dirección exacta de entrega.');return}let productsTotal=items.reduce((s,it)=>s+it.product.price*it.qty,0);let deliveryCost=delivery==='yes'?Number(zone.price)||0:0;let total=productsTotal+deliveryCost;let wa=document.getElementById('waChoice').value;if(Date.now()-Number(lsGet('tm_last_send')||0)<15000){notify('Tu pedido ya se envió hace un momento. Espera unos segundos.');return}window.tmSending=true;lsSet('tm_last_send',String(Date.now()));const sendBtn=document.getElementById('sendBtn');tmSendMorph(sendBtn);const minWait=new Promise(r=>setTimeout(r,1000));let info=await registerOrder({name,phone,delivery,zone,address,items,productsTotal,deliveryCost,total,notes:document.getElementById('customerNotes').value.trim()});await minWait;window.tmSending=false;let msg=`🌮 *NUEVO PEDIDO — TACOS MISHOS*\n\n*Cliente:* ${name}\n*Teléfono:* ${phone}\n*Servicio:* ${delivery==='yes'?'Entrega a domicilio':'Recogida en el local'}\n${delivery==='yes'?`*Reparto:* ${zone.name}\n*Dirección exacta:* ${address}\n*Costo del domicilio:* ${money(deliveryCost)}\n`:''}\n*Productos:*\n`+items.map(it=>`• ${it.product.name}${it.proteins.length?' — Proteínas: '+it.proteins.join(' + '):''} x${it.qty} — ${money(it.product.price*it.qty)}`).join('\n')+`\n\n*Subtotal productos: ${money(productsTotal)}*\n${delivery==='yes'?`*Domicilio: ${money(deliveryCost)}*\n`:''}*TOTAL DEL PEDIDO: ${money(total)}*\n*Indicaciones:* ${document.getElementById('customerNotes').value.trim()||'Ninguna'}\n\n${info.premio?'🎁 *Premio de fidelidad:* '+info.premio+'\n\n':''}_Por favor, confirmar disponibilidad y entrega._`;const waUrl=`https://wa.me/${wa}?text=${encodeURIComponent(msg)}`;rememberCustomer(name,phone,address,zone?zone.name:'',delivery);lsSet('tm_sent_v1',JSON.stringify({url:waUrl,total,n:items.reduce((a,x)=>a+x.qty,0),t:Date.now()}));window.tmSugOff=false;lsSet('tm_last_cart_v1',JSON.stringify(cart));cart={};saveCart();updateCartCount();renderCart();document.getElementById('customerNotes').value='';closeModal('cartModal');tmSendReset(sendBtn);renderSent();let w=null;try{w=window.open(waUrl,'_blank')}catch(e){}if(!w){location.href=waUrl;}else{notify('Se abrió WhatsApp con tu pedido. El carrito quedó vacío.');}}


let selectedStars=5;
function setStars(n){selectedStars=Math.max(1,Math.min(5,Number(n)||5));document.querySelectorAll('#starPicker button').forEach((b,i)=>b.textContent=i<selectedStars?'★':'☆');}
function formatReviewDate(value){try{return new Intl.DateTimeFormat('es-CU',{timeZone:'America/Havana',dateStyle:'medium'}).format(new Date(value));}catch{return '';}}
function renderSharedReviews(reviews){const list=document.getElementById('reviewList');if(!list)return;list.innerHTML=reviews.length?reviews.map(r=>`<article class="review"><b>${esc(r.nombre)}</b> <span style="color:#00473c">${'★'.repeat(Number(r.estrellas)||0)}${'☆'.repeat(5-(Number(r.estrellas)||0))}</span><p style="margin:7px 0 0;line-height:1.5">${esc(r.comentario)}</p>${r.producto_nombre?`<small class="tiny">Producto: ${esc(r.producto_nombre)}</small><br>`:''}<small class="tiny">${esc(formatReviewDate(r.creado_en))}</small></article>`).join(''):'<p class="tiny">Todavía no hay reseñas publicadas. ¡Sé el primero en compartir tu experiencia!</p>';}
async function loadSharedReviews(){const list=document.getElementById('reviewList');if(!list)return;if(!window.tmSupabase){list.innerHTML='<p class="tiny">No se pudo conectar con el servicio de reseñas. Comprueba la conexión a Internet.</p>';return;}list.setAttribute('aria-busy','true');list.innerHTML=Array(3).fill('<div class="review skel-rev" aria-hidden="true"><div class="skel skel-line w40"></div><div class="skel skel-line w90"></div><div class="skel skel-line w70"></div></div>').join('');try{const {data,error}=await window.tmSupabase.from('resenas').select('id,nombre,estrellas,comentario,creado_en,producto_id,producto_nombre').eq('aprobada',true).order('creado_en',{ascending:false}).limit(100);if(error)throw error;renderSharedReviews(data||[]);}catch(err){console.error('Error al cargar reseñas compartidas:',err);list.innerHTML='<p class="tiny">Las reseñas compartidas aún no están configuradas. El administrador debe ejecutar el archivo CONFIGURAR-RESENAS.sql en Supabase.</p>';}}
async function submitReview(e){e.preventDefault();const name=document.getElementById('reviewName').value.trim(),comment=document.getElementById('reviewText').value.trim(),btn=e.submitter||document.querySelector('.review-form button[type="submit"]');if(!name||!comment)return;if(!/^[A-Za-zÁÉÍÓÚÜÑáéíóúüñ]+(?:[ '’-][A-Za-zÁÉÍÓÚÜÑáéíóúüñ]+)*$/.test(name)){notify('El nombre solo puede contener letras y espacios.');document.getElementById('reviewName').focus();return;}if(document.getElementById('reviewWebsite')&&document.getElementById('reviewWebsite').value)return;if(Date.now()-Number(lsGet('tm_last_review')||0)<120000){notify('Espera un par de minutos antes de enviar otra reseña.');return;}if(!window.tmSupabase){notify('No se puede conectar con el servicio de reseñas. Inténtalo de nuevo cuando tengas conexión.');return;}if(btn)btn.disabled=true;try{const productId=document.getElementById('reviewProduct').value||null;const productName=products.find(p=>String(p.id)===String(productId))?.name||null;const {error}=await window.tmSupabase.from('resenas').insert({nombre:name,estrellas:selectedStars,comentario:comment,producto_id:productId,producto_nombre:productName});if(error)throw error;document.getElementById('reviewText').value='';lsSet('tm_last_review',String(Date.now()));document.getElementById('reviewName').value='';notify('¡Gracias! Recibimos tu reseña y la publicaremos en cuanto la revisemos.');}catch(err){console.error('Error al publicar reseña:',err);notify('No se pudo publicar la reseña. Es posible que falte configurar la tabla de reseñas en Supabase. Revisa el archivo CONFIGURAR-RESENAS.sql.');}finally{if(btn)btn.disabled=false;}}
