function havanaNow(){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Havana',weekday:'short',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date());const o={};parts.forEach(x=>o[x.type]=x.value);return {day:o.weekday,h:+o.hour,m:+o.minute,s:+o.second};}
function updateBusinessStatus(){const n=havanaNow(),dayMap={Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6,Sun:0},d=dayMap[n.day],mins=n.h*60+n.m,openAt=17*60,closeAt=d===0?22*60:21*60;let isOpen=(d>=1&&d<=5||d===0)&&mins>=openAt&&mins<closeAt;let text='';if(isOpen){let remaining=closeAt*60-(mins*60+n.s),h=Math.floor(remaining/3600),m=Math.floor((remaining%3600)/60),sec=remaining%60;text=`🌮 ¡Estamos abiertos! · Cerramos en ${h} h ${m} min${h===0&&m===0?` ${sec} s`:''}`;}else{let next='';if(d===6)next='Abrimos el domingo a las 5:00 p. m.';else if(d===0&&mins>=22*60)next='Abrimos el lunes a las 5:00 p. m.';else if(d>=1&&d<=5&&mins<17*60)next='Abrimos hoy a las 5:00 p. m.';else if(d>=1&&d<=5&&mins>=21*60)next=d===5?'Abrimos el domingo a las 5:00 p. m.':'Abrimos mañana a las 5:00 p. m.';text=`🌮 Ahora estamos cerrados · ${next}`;}if(siteSettings.store_closed===true){isOpen=false;text='🌮 Hoy estamos cerrados · Volvemos pronto';}window.tmClosedMsg=isOpen?'':'🕒 '+text.replace('🌮 ','')+' · Deja tu pedido y te respondemos al abrir';try{applyTicker()}catch(e){}const cb=document.getElementById('closedBanner');if(cb){if(cb.textContent!==window.tmClosedMsg)cb.textContent=window.tmClosedMsg;cb.hidden=isOpen}window.tmStoreOpen=isOpen;const cn=document.getElementById('closedNotice');if(cn){cn.classList.toggle('hidden',isOpen);cn.textContent=siteSettings.store_closed===true?'🔒 Hoy estamos cerrados. Puedes armar tu pedido y te respondemos en cuanto abramos.':'🕒 Ahora estamos cerrados. Puedes armar tu pedido y te respondemos en cuanto abramos.';}const el=document.getElementById('businessStatus');if(el){el.textContent=text;el.className='topbar '+(isOpen?'status-open':'status-closed')}const a=document.getElementById('aboutStatus');if(a)a.textContent=text.replace('🌮 ','');}
