(function setupStickyAnnouncementTicker() {
  const ticker = document.getElementById('announcementTicker');
  const nav = document.querySelector('.nav');
  if (!ticker || !nav) return;
  let originalTop = 0;
  let ticking = false;
  function measure() {
    const wasFixed = ticker.classList.contains('is-fixed');
    ticker.classList.remove('is-fixed');
    document.body.classList.remove('ticker-fixed-active');
    originalTop =
      ticker.getBoundingClientRect().top + window.scrollY;
    document.documentElement.style.setProperty(
      '--tm-ticker-height',
      ticker.offsetHeight + 'px'
    );
    if (wasFixed) update();
  }
  function update() {
    ticking = false;
    const shouldFix = window.scrollY >= originalTop;
    ticker.classList.toggle('is-fixed', shouldFix);
    document.body.classList.toggle(
      'ticker-fixed-active',
      shouldFix
    );
  }
  window.addEventListener('scroll', () => {
    if (!ticking) {
      ticking = true;
      requestAnimationFrame(update);
    }
  }, { passive: true });
  window.addEventListener('resize', measure);
  measure();
})();
  (function syncStickyStack(){
  const root   = document.documentElement;
  const ticker = document.getElementById('announcementTicker');
  const nav    = document.querySelector('.nav');
  if(!nav) return;

  function update(){
    root.style.setProperty('--tm-ticker-height', (ticker ? ticker.offsetHeight : 0) + 'px');
    root.style.setProperty('--tm-nav-height', nav.offsetHeight + 'px');
  }

  update();
  window.addEventListener('resize', update);
  window.addEventListener('load', update);
  window.addEventListener('orientationchange', update);
  if('ResizeObserver' in window){
    const ro = new ResizeObserver(update);
    ro.observe(nav);
    if(ticker) ro.observe(ticker);
  }
})();
